        },
        user: {
          email: s.customer.email
        },
        ts: new Date(webhook.payload.timestamp).getTime()
      };
      break;
    case "subscription.cancelled":
      webhook.payload = {
        name: "subscription.cancelled",
        data: {
          subscription_id: s.subscription_id,
          customer_email: s.customer.email,
          cancelled_at: s.cancelled_at,
          cancel_at_next_billing: s.cancel_at_next_billing_date
        },
        user: {
          email: s.customer.email
        },
        ts: new Date(webhook.payload.timestamp).getTime()
      };
      break;
  }
  return webhook;
}
```

### Dispute Event Handler

This handler forwards every `dispute.*` event and marks `dispute.opened` as urgent. Dispute payloads include the customer who filed the dispute in `customer`, so it sends the customer's email in `user`.

